-- Restore Brewmoon Festival (map 1051, scenario 63).
-- Spawn and text data were ported read-only from Legends of Azeroth
-- Pandaria 5.4.8 (build 18414); scripts were adapted to Legion 7.3.5.
-- Legion build 26972 DB2 confirms four steps, their criteria, and LFG dungeon 539.
START TRANSACTION;

-- Replace the unscripted population with the coherent MoP scenario population.
-- In particular, the assault waves and Warbringer Qobi are summoned by C++ in chapter order.
DELETE `ca` FROM `creature_addon` `ca` INNER JOIN `creature` `c` ON `c`.`guid`=`ca`.`guid` WHERE `c`.`map`=1051;
DELETE `wp` FROM `waypoint_data` `wp` INNER JOIN `creature` `c` ON `c`.`guid`=`wp`.`id` WHERE `c`.`map`=1051;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`memberGUID` WHERE `c`.`map`=1051;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`leaderGUID` WHERE `c`.`map`=1051;
DELETE `gec` FROM `game_event_creature` `gec` INNER JOIN `creature` `c` ON `c`.`guid`=`gec`.`guid` WHERE `c`.`map`=1051;
DELETE `pc` FROM `pool_creature` `pc` INNER JOIN `creature` `c` ON `c`.`guid`=`pc`.`guid` WHERE `c`.`map`=1051;
DELETE `geg` FROM `game_event_gameobject` `geg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`geg`.`guid` WHERE `go`.`map`=1051;
DELETE `pg` FROM `pool_gameobject` `pg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`pg`.`guid` WHERE `go`.`map`=1051;
DELETE FROM `creature` WHERE `map`=1051;
DELETE FROM `gameobject` WHERE `map`=1051;



-- Bind static and dynamically summoned scenario actors.
UPDATE `creature_template` SET `ScriptName`='npc_den_mother_moof' WHERE `entry`=63518;
UPDATE `creature_template` SET `ScriptName`='npc_li_te' WHERE `entry`=63520;
UPDATE `creature_template` SET `ScriptName`='npc_karsar_bloodletter' WHERE `entry`=63529;
UPDATE `creature_template` SET `ScriptName`='npc_disturbed_saurok' WHERE `entry`=63521;
UPDATE `creature_template` SET `ScriptName`='npc_brewmoon_water_spirit' WHERE `entry`=63519;
UPDATE `creature_template` SET `ScriptName`='npc_binan_villager' WHERE `entry`=62784;
UPDATE `creature_template` SET `ScriptName`='npc_brewmoon_fireworks_barrel' WHERE `entry`=63940;
UPDATE `creature_template` SET `ScriptName`='npc_assistant_tart' WHERE `entry`=62793;
UPDATE `creature_template` SET `ScriptName`='npc_tarts_boat' WHERE `entry`=63826;
UPDATE `creature_template` SET `ScriptName`='npc_assistant_kieu' WHERE `entry`=62787;
UPDATE `creature_template` SET `ScriptName`='npc_brewmaster_boof' WHERE `entry`=64901;
UPDATE `creature_template` SET `ScriptName`='npc_bataari_yaungol' WHERE `entry`=63527;
UPDATE `creature_template` SET `ScriptName`='npc_bataari_flamecaller' WHERE `entry`=63526;
UPDATE `creature_template` SET `ScriptName`='npc_bataari_outrunner' WHERE `entry`=64165;
UPDATE `creature_template` SET `ScriptName`='npc_bataari_war_yeti' WHERE `entry`=64185;
UPDATE `creature_template` SET `ScriptName`='npc_warbringer_qobi' WHERE `entry`=63528;
UPDATE `creature_template` SET `ScriptName`='npc_brewmoon_fireline' WHERE `entry`=64265;

DELETE FROM `spell_script_names` WHERE `spell_id` IN (124378,124752,125302,125330);

DELETE FROM `areatrigger_scripts` WHERE `entry`=8554;

DELETE FROM `creature_text` WHERE `CreatureID` IN (62787,62793,63520,63528,63811,63812,63818,64185,64901,65295);

ON DUPLICATE KEY UPDATE `parent`=VALUES(`parent`),`script`=VALUES(`script`),`allowMount`=VALUES(`allowMount`);

DELETE FROM `scenario_data` WHERE `MapID`=1051 OR `ScenarioID`=63;

-- Enable only after all spawn, text, script, and scenario data is installed.
DELETE FROM `disables` WHERE `sourceType`=2 AND `entry`=1051;

COMMIT;
